function toHookError(rejection: unknown): Error {
  if (rejection instanceof Error) return rejection;
  return new Error(describeRejection(rejection), {cause: rejection});
}

function describeRejection(rejection: unknown): string {
  if (typeof rejection === 'string') return rejection;
  return serializedOrNull(rejection) ?? String(rejection);
}

// JSON.stringify throws on circular objects and BigInt, and returns undefined for undefined, functions, and symbols.
function serializedOrNull(value: unknown): string | null {
  try {
    return JSON.stringify(value) ?? null;
  } catch {
    return null;
  }
}

